function rtForm(string $action,?array $c=null):void{echo '<form method="post" enctype="multipart/form-data">';csrf();echo '<input type="hidden" name="action" value="'.e($action).'">';if($c)echo '<input type="hidden" name="cohort_id" value="'.$c['id'].'"><input type="hidden" name="revision" value="'.$c['revision'].'">';}
function rtField(string $key,string $label,string $value='',string $type='text'):void{echo '<label>'.e($label).'<input type="'.e($type).'" name="'.e($key).'" value="'.e($value).'" required></label>';}
