<?php if($page==='rt_settings'):$settings=rtSettings();?><section class="card"><h2>Print settings</h2><p>Applies to new batches. Existing drafts can explicitly adopt these settings. Sign and apply the physical seal after printing. Please verify the Dzongkha spelling before issuing results.</p><?php rtForm('rt_settings');?><div class="form-grid"><?php foreach(['dean'=>'Dean of Academic Affairs name','president'=>'President name','heading'=>'Document heading','dz_university'=>'University heading (Dzongkha)','dz_college'=>'College heading (Dzongkha)']as $k=>$label)rtField($k,$label,$settings[$k]);foreach(['rub_logo'=>'RUB logo','cnr_logo'=>'College logo']as $k=>$label):?><label><?=e($label)?> (optional replacement, PNG/JPEG ≤2 MB)<input type="file" name="<?=$k?>" accept=".png,.jpg,.jpeg"><img class="rt-logo-preview" src="<?=e(rtLogoData($settings[$k]))?>" alt="<?=e($label)?>"></label><?php endforeach;?></div><button>Save print settings</button></form></section><?php return;endif;?>
<?php if(!$id):?><section class="card"><h2>Create a result batch</h2><p>Create one batch per programme and intake. Upload successive semesters into the same batch. Use a separate batch for a curriculum with different modules. Two-year programmes use 30:70; three-year 20:30:50; four-year 10:20:30:40.</p><?php rtForm('rt_create');?><div class="form-grid"><?php rtField('title','Batch name (e.g. Animal Science 2021–2025)');rtField('programme','Programme / award name as printed');?><label>Programme duration<select name="duration" required><option value="4">4 years / 8 semesters</option><option value="3">3 years / 6 semesters</option><option value="2">2 years / 4 semesters (diploma)</option></select></label><?php rtField('study_period','Period of study (e.g. July 2021 – June 2025)');rtField('issued_on','Issue date',date('Y-m-d'),'date');?></div><button>Create result batch</button></form></section><section class="card"><h2>Result batches</h2><div class="table-wrap"><table><tr><th>Batch</th><th>Programme</th><th>Status</th><th>Created</th><th>Actions</th></tr><?php foreach(all('SELECT * FROM result_cohorts ORDER BY id DESC')as $c):?><tr><td><a href="?page=rt_home&amp;cohort_id=<?=$c['id']?>"><?=e($c['title'])?></a></td><td><?=e($c['programme'])?></td><td><?=e($c['status'])?></td><td><?=e($c['created_at'])?></td><td><div class="ac-toolbar"><a class="button secondary" href="?page=rt_home&amp;cohort_id=<?=$c['id']?>&amp;manage=edit#rt-edit">Edit</a><a class="button danger-button" href="?page=rt_home&amp;cohort_id=<?=$c['id']?>&amp;manage=delete#rt-delete">Delete</a></div></td></tr><?php endforeach;?></table></div></section><?php return;endif;
