<?php if($draft):?><section class="card"><h2>Upload semester marks</h2><p>Use the nine-column CSV template or an XLSX file with the same headings on its first sheet. Enter semester numbers consecutively (1–<?=$c['duration']*2?>). One row per student and module. Keep student numbers as text to preserve leading zeros. Upload final approved marks, including any approved re-assessment adjustments; this portal does not infer CA/ESE pass decisions.</p><?php rtForm('rt_preview',$c);?><label>Marks file (CSV/XLSX, up to 10 MB)<input type="file" name="marks" accept=".csv,.xlsx" required></label><label class="period-delete-confirm"><input type="checkbox" name="correction" value="1"><span>Correction mode: replace conflicting marks after preview</span></label><label>Reason for correction (required for correction mode)<input name="reason" maxlength="1000"></label><button>Validate and preview</button></form></section>
<?php if(($v['id']??0)===$id):?><section class="card"><h2>Upload preview</h2><p><?=count($v['rows'])?> rows · <?=$v['changed']?> new/changed · <?=$v['same']?> identical. Nothing is saved until you confirm. Showing the first 50 rows.</p><div class="table-wrap"><table><tr><th>Student</th><th>Name</th><th>Semester</th><th>Module</th><th>Mark / max.</th><th>Credit</th></tr><?php foreach(array_slice($v['rows'],0,50)as $r):?><tr><td><?=e($r['student_number'])?></td><td><?=e($r['student_name'])?></td><td><?=$r['semester']?></td><td><?=e($r['module_code'])?></td><td><?=e($r['mark'].' / '.$r['maximum'])?></td><td><?=e($r['credits'])?></td></tr><?php endforeach;?></table></div><?php rtForm('rt_commit',$c);?><label class="period-delete-confirm"><input type="checkbox" name="confirmed" value="1" required><span>I checked the preview and confirm this import.</span></label><button>Save validated marks</button></form></section><?php endif;endif;?>
<section class="card"><h2>Students and completeness</h2><p>Missing modules are checked against the combined module list uploaded for this batch. This cannot detect a module or student omitted from every upload. Exam Cell must verify the official curriculum and roster before finalizing. Percentage and performance describe uploaded final marks, not an independent award-eligibility decision.</p><div class="table-wrap"><table><tr><th>No.</th><th>Student number</th><th>Name</th><th>Percentage</th><th>Performance</th><th>Completeness</th><th>Print</th></tr><?php $n=0;foreach($students as $sid=>$s):?><tr><td><?=++$n?></td><td><?=e((string)$sid)?></td><td><?=e($s['name'])?></td><td><?=number_format($s['percent'],2)?>%</td><td><?=e($s['performance'])?></td><td><?=$s['complete']?'All uploaded modules present':e($s['missing'].' missing modules; missing semesters: '.implode(', ',$s['missing_semesters']))?></td><td><a target="_blank" href="?<?=e(http_build_query(['page'=>'rt_print','cohort_id'=>$id,'student'=>(string)$sid]))?>">Preview / print</a></td></tr><?php endforeach;?></table></div></section>
<section class="card" id="<?=$draft?'rt-finalize':'rt-edit'?>"><h2><?=$draft?'Finalize for printing':'Reopen for correction'?></h2><?php rtForm($draft?'rt_finalize':'rt_reopen',$c);rtField('reason',$draft?'Verification note':'Reason for reopening');if($draft):?><label class="period-delete-confirm"><input type="checkbox" name="confirmed" value="1" required><span>I verified every student, all curriculum modules, final approved marks, signatories, Dzongkha header and print preview.</span></label><?php else:?><p>Previously issued copies will not update. Reprint affected results after correction and finalization.</p><?php endif;?><button><?=$draft?'Finalize batch':'Reopen batch'?></button></form></section>
<?php if($draft):?><section class="card"><details id="rt-edit" <?=($_GET['manage']??'')==='edit'?'open':''?>><summary>Edit batch details / update print settings</summary><?php rtForm('rt_metadata',$c);?><div class="form-grid"><?php foreach(['title'=>'Batch name','programme'=>'Programme / award','study_period'=>'Period of study']as $k=>$label)rtField($k,$label,$c[$k]);rtField('issued_on','Issue date',$c['issued_on'],'date');rtField('reason','Reason for change');?></div><label class="period-delete-confirm"><input type="checkbox" name="refresh_settings" value="1"><span>Use the latest saved signatory, header and logo settings</span></label><button>Save batch details</button></form></details><details><summary>Remove a mistakenly uploaded student</summary><p>Removes this student's marks from this batch only; audit history is retained.</p><?php rtForm('rt_remove',$c);rtField('student_number','Exact student number');rtField('reason','Reason');?><label class="period-delete-confirm"><input type="checkbox" name="confirmed" value="1" required><span>I confirm removal of this student's marks from this batch.</span></label><button class="danger-button">Remove student from batch</button></form></details></section><?php endif;?>
<section class="card"><details><summary>Audit history</summary><?php foreach(all('SELECT a.*,u.name FROM result_audit a JOIN users u ON u.id=a.actor_id WHERE cohort_id=? ORDER BY a.id DESC',[$id])as $a):$detail=json_decode($a['details'],true);?><p><strong><?=e($a['action'])?></strong> · <?=e($a['name'].' · '.$a['created_at'])?><br><?=e($detail['reason']??'')?></p><?php endforeach;?></details></section>
